Types.Decl:
type Bar struct {
	// Date is the day in the admin language, such as "5 okt 2026".
	Date     string
	Views    int
	Visitors int
	Height   int
}

type Count struct {
	Name     string `db:"name"`
	Views    int    `db:"views"`
	Visitors int    `db:"visitors"`
}

type Day struct {
	// Date is YYYY-MM-DD.
	Date     string `db:"day"`
	Views    int    `db:"views"`
	Visitors int    `db:"visitors"`
}

type Page struct {
	// Path is the page's address, for example /en/news/hello.
	Path string `db:"path"`
	// Title is the page's HTML title when it was last viewed, without the
	// site name.
	Title    string `db:"title"`
	Views    int    `db:"views"`
	Visitors int    `db:"visitors"`
}

type RangeLink struct {
	Days   int
	URL    string
	Active bool
}

type Report struct {
	Days int
	// Views and Visitors are the totals. A visitor is recognised for one day
	// only, so Visitors adds up the visitors of each day.
	Views     int
	Visitors  int
	Daily     []Day
	Pages     []Page
	Referrers []Count
	Devices   []Count
	Locales   []Count
}

type Service struct {
	// contains unexported fields
}
